'use strict';

function normalise(value) {
  return String(value ?? '').trim().toLowerCase();
}

const FIX_SCENARIOS = new Set([
  'ci',
  'ci-failure',
  'ci_failure',
  'fix',
  'fix-ci',
  'fix_ci',
  'fix-ci-failure',
]);

const VERIFY_SCENARIOS = new Set([
  'verify',
  'verification',
  'verify-acceptance',
  'acceptance',
]);

const FEATURE_SCENARIOS = new Set([
  'feature',
  'feature-work',
  'feature_work',
  'task',
  'next-task',
  'next_task',
  'nexttask',
]);

const FIX_MODES = new Set(['fix', 'fix-ci', 'fix_ci', 'ci', 'ci-failure']);
const VERIFY_MODES = new Set(['verify', 'verification', 'verify-acceptance', 'acceptance']);

function resolvePromptMode({ scenario, mode, action, reason } = {}) {
  const modeValue = normalise(mode);
  if (modeValue) {
    if (FIX_MODES.has(modeValue)) {
      return 'fix_ci';
    }
    if (VERIFY_MODES.has(modeValue)) {
      return 'verify';
    }
    return 'normal';
  }

  const actionValue = normalise(action);
  const reasonValue = normalise(reason);
  if (actionValue === 'fix' || reasonValue.startsWith('fix-')) {
    return 'fix_ci';
  }
  if (actionValue === 'verify' || reasonValue === 'verify-acceptance') {
    return 'verify';
  }

  const scenarioValue = normalise(scenario);
  if (scenarioValue) {
    if (FIX_SCENARIOS.has(scenarioValue)) {
      return 'fix_ci';
    }
    if (VERIFY_SCENARIOS.has(scenarioValue)) {
      return 'verify';
    }
    if (FEATURE_SCENARIOS.has(scenarioValue)) {
      return 'normal';
    }
  }

  return 'normal';
}

module.exports = {
  resolvePromptMode,
};

'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');

const { resolvePromptMode } = require('../keepalive_prompt_routing');

test('resolvePromptMode routes ci failure scenarios to fix_ci', () => {
  assert.equal(resolvePromptMode({ scenario: 'ci-failure' }), 'fix_ci');
  assert.equal(resolvePromptMode({ scenario: 'fix-ci' }), 'fix_ci');
});

test('resolvePromptMode routes feature scenarios to normal', () => {
  assert.equal(resolvePromptMode({ scenario: 'feature-work' }), 'normal');
  assert.equal(resolvePromptMode({ scenario: 'next-task' }), 'normal');
  assert.equal(resolvePromptMode({ scenario: 'next_task' }), 'normal');
  assert.equal(resolvePromptMode({ scenario: 'nexttask' }), 'normal');
});

test('resolvePromptMode routes verification scenarios to verify', () => {
  assert.equal(resolvePromptMode({ scenario: 'verification' }), 'verify');
  assert.equal(resolvePromptMode({ scenario: 'verify-acceptance' }), 'verify');
});

test('resolvePromptMode falls back to action or reason when scenario/mode missing', () => {
  assert.equal(resolvePromptMode({ action: 'fix' }), 'fix_ci');
  assert.equal(resolvePromptMode({ reason: 'fix-build' }), 'fix_ci');
  assert.equal(resolvePromptMode({ action: 'verify' }), 'verify');
  assert.equal(resolvePromptMode({ reason: 'verify-acceptance' }), 'verify');
});

test('resolvePromptMode prioritizes fix/verify actions over scenario', () => {
  assert.equal(resolvePromptMode({ scenario: 'feature-work', action: 'fix' }), 'fix_ci');
  assert.equal(resolvePromptMode({ scenario: 'feature-work', reason: 'verify-acceptance' }), 'verify');
});
